#!/usr/bin/env node
// Captures the price-gate fixture (specs/pricing-components.md §3 rules 68 and 71) from a COPY of a real database.
//
//   node scripts/price-gate/buildFixture.mjs <copy.db> --out server/src/tests/fixtures/price-gate/
//
// PASS A COPY, NEVER THE ORIGINAL: the application's own boot migrates the file it opens (and the lazy repairs
// of a read may write), so a path under `shadows/` is refused unless `--i-am-a-copy` says you made it one. The
// fixture is captured ONCE, on the code of the `price-gate-baseline` tag, and is never regenerated by the code of
// PR A, B or C (that would bless their changes).
//
// What it does: freezes the clock at CAPTURED_AT, boots the application on the copy, copies the allow-listed
// columns (`anonymise.js`), computes the figures of every stay and devis with the CURRENT code
// (`recompute.js`) and replays every stored intake on its stay, then writes:
//   inputs.json    { meta, tables, synthetic }   the anonymised rows the engine reads; `synthetic` = { cases, tables }
//   expected.json  { meta, stays, resourceBookings, propertyGrids, synthetic }  the figures per reservation id, each read at the four
//                  instants of `recompute.js`, and per standalone resource booking id; `synthetic` = { cases, stays, resourceBookings, propertyGrids }
//   quotes.json    { meta, stays, synthetic }    the whole-quote fingerprints per reservation id: { keys, hash }
//   intakes.json   { meta, tables, expected, synthetic } the anonymised intakes and what their replay produced; `synthetic` =
//                  { tables, expected }: the crafted intakes of the synthetic platform stays and what their replay produced
// Prints ids and counts only — never a name.
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createRequire } from 'node:module';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

// The day the prices are read on: every "today" of the engine (tourist-tax freeze, due dates, locked stays).
const CAPTURED_AT = '2026-11-11T12:00:00+01:00';

const args = process.argv.slice(2);
const flag = (name) => (args.includes(name) ? args[args.indexOf(name) + 1] : null);
const dbPath = args[0] && !args[0].startsWith('--') ? path.resolve(args[0]) : null;
const outDir = flag('--out');
if (!dbPath || !outDir || !fs.existsSync(dbPath)) {
  console.error('usage: buildFixture.mjs <copy.db> --out <dir> [--i-am-a-copy] [--no-verify]   (pass a COPY of the database)');
  process.exit(2);
}
if (dbPath.split(path.sep).includes('shadows') && !args.includes('--i-am-a-copy')) {
  console.error('refused: that path is under shadows/ — copy the snapshot to a temporary folder and pass the copy (or --i-am-a-copy)');
  process.exit(2);
}

process.env.DB_PATH = dbPath;
process.env.TZ = 'Europe/Paris';
const { freezeClock } = require(path.join(root, 'server/src/tests/vatRegimeGoldenFixture.js'));
freezeClock(new Date(CAPTURED_AT));

const print = console.log;
console.log = () => {};
const { mock } = require('node:test');
const db = require(path.join(root, 'server/src/database.js'));
const { anonymise, ALLOW_LIST, INTAKE_TABLES } = require('./anonymise.js');
const { recomputeStays, replayIntakes, replayGdfFixtures } = require('./recompute.js');

const present = new Set(db.prepare("SELECT name FROM sqlite_master WHERE type = 'table'").all().map((r) => r.name));
const source = {};
for (const table of Object.keys(ALLOW_LIST)) {
  if (present.has(table)) source[table] = db.prepare(`SELECT * FROM ${table} ORDER BY rowid`).all();
}
const copied = anonymise(source);
const inputsTables = Object.fromEntries(Object.entries(copied).filter(([t]) => !INTAKE_TABLES.includes(t)).sort(([a], [b]) => a.localeCompare(b)));
const intakesTables = Object.fromEntries(INTAKE_TABLES.map((t) => [t, copied[t] || []]));

mock.timers.enable({ apis: ['Date'], now: new Date(CAPTURED_AT).getTime() });
const pinClock = (instant) => { mock.timers.setTime(new Date(instant).getTime()); return () => mock.timers.setTime(new Date(CAPTURED_AT).getTime()); };
const stays = recomputeStays(db, { capturedAt: CAPTURED_AT, pinClock });
const intakesExpected = [...replayIntakes(db, { tables: intakesTables }, pinClock), ...replayGdfFixtures(db, pinClock)];
mock.timers.reset();
console.log = print;

// The synthetic refund stays (rule 72) are played on an empty in-memory database in a process of their own.
const syntheticFile = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'price-gate-synthetic-')), 'synthetic.json');
const played = spawnSync('node', [path.join(root, 'scripts/price-gate/buildSynthetic.js'), CAPTURED_AT, syntheticFile], {
  encoding: 'utf8', env: { ...process.env, DB_PATH: ':memory:' },
});
if (played.status !== 0) {
  console.log = print;
  console.error(`synthetic refund stays failed:\n${played.stdout}\n${played.stderr}`);
  process.exit(1);
}
const synthetic = JSON.parse(fs.readFileSync(syntheticFile, 'utf8'));
fs.rmSync(path.dirname(syntheticFile), { recursive: true, force: true });

// The whole-quote fingerprints (rule 4): the quote of every stay, key for key, on the baseline code — loaded from the
// anonymised rows just written, in a process of its own.
const fingerprints = {};
const quotesDir = fs.mkdtempSync(path.join(os.tmpdir(), 'price-gate-quotes-'));
fs.mkdirSync(outDir, { recursive: true });
const metaNow = { capturedAt: CAPTURED_AT, note: 'captured once on the price-gate-baseline code; never regenerated by PR A, B or C' };
fs.writeFileSync(path.join(quotesDir, 'inputs.json'), `${JSON.stringify({ meta: metaNow, tables: inputsTables, synthetic: { cases: synthetic.cases, tables: synthetic.tables } })}\n`);
for (const section of ['production', 'synthetic']) {
  const target = path.join(quotesDir, `${section}.json`);
  const ran = spawnSync('node', [path.join(root, 'scripts/price-gate/buildQuoteHashes.js'), CAPTURED_AT, path.join(quotesDir, 'inputs.json'), section, target], {
    encoding: 'utf8', env: { ...process.env, DB_PATH: ':memory:' },
  });
  if (ran.status !== 0) {
    console.log = print;
    console.error(`quote fingerprints (${section}) failed:\n${ran.stdout}\n${ran.stderr}`);
    process.exit(1);
  }
  fingerprints[section] = JSON.parse(fs.readFileSync(target, 'utf8'));
}
// The standalone resource bookings, read on a database loaded from the anonymised rows (the copy's plugin tables may lack
// the columns of a newer plugin version): the figures are those the gate reads, in a process of its own.
const bookingsFile = path.join(quotesDir, 'resource-bookings.json');
const booked = spawnSync('node', [path.join(root, 'scripts/price-gate/buildResourceBookings.js'), CAPTURED_AT, path.join(quotesDir, 'inputs.json'), bookingsFile], {
  encoding: 'utf8', env: { ...process.env, DB_PATH: ':memory:' },
});
if (booked.status !== 0) {
  console.log = print;
  console.error(`resource bookings failed:\n${booked.stdout}\n${booked.stderr}`);
  process.exit(1);
}
const { resourceBookings, propertyGrids } = JSON.parse(fs.readFileSync(bookingsFile, 'utf8'));
// The crafted intakes of the synthetic platform stays, replayed on a database loaded from the anonymised synthetic rows.
const intakesFile = path.join(quotesDir, 'intakes.json');
fs.writeFileSync(intakesFile, `${JSON.stringify({ synthetic: { tables: synthetic.intakes } })}\n`);
const syntheticIntakesFile = path.join(quotesDir, 'synthetic-intakes.json');
const replayed = spawnSync('node', [path.join(root, 'scripts/price-gate/replaySyntheticIntakes.js'), CAPTURED_AT, path.join(quotesDir, 'inputs.json'), intakesFile, syntheticIntakesFile], {
  encoding: 'utf8', env: { ...process.env, DB_PATH: ':memory:' },
});
if (replayed.status !== 0) {
  console.log = print;
  console.error(`synthetic intakes failed:\n${replayed.stdout}\n${replayed.stderr}`);
  process.exit(1);
}
const syntheticIntakes = { tables: synthetic.intakes, expected: JSON.parse(fs.readFileSync(syntheticIntakesFile, 'utf8')) };
fs.rmSync(quotesDir, { recursive: true, force: true });

const meta = { capturedAt: CAPTURED_AT, note: 'captured once on the price-gate-baseline code; never regenerated by PR A, B or C' };
const write = (name, value) => fs.writeFileSync(path.join(outDir, name), `${JSON.stringify(value, null, 1)}\n`);
fs.mkdirSync(outDir, { recursive: true });
write('inputs.json', { meta, tables: inputsTables, synthetic: { cases: synthetic.cases, resourceBookingCases: synthetic.resourceBookingCases, tables: synthetic.tables } });
write('expected.json', { meta, stays, resourceBookings, propertyGrids, synthetic: { cases: synthetic.cases, stays: synthetic.stays, resourceBookings: synthetic.resourceBookings, propertyGrids: synthetic.propertyGrids } });
write('quotes.json', { meta, stays: fingerprints.production, synthetic: fingerprints.synthetic });
write('intakes.json', { meta, tables: intakesTables, expected: intakesExpected, synthetic: syntheticIntakes });

const all = Object.values(stays);
const count = (pick) => all.filter(pick).length;
print(`captured at ${CAPTURED_AT}`);
print(`stays: ${all.length} (reservations ${count((s) => s['kind@capture'] === 'reservation')}, cancelled ${count((s) => s['kind@capture'] === 'cancelled')}, devis ${count((s) => s['kind@capture'] === 'devis')}, platform sales ${count((s) => s['platform.sale@capture'] === true)})`);
print(`resource bookings: ${Object.keys(resourceBookings).length}, property grids: ${Object.keys(propertyGrids).length}`);
print(`synthetic refund stays: ${Object.entries(synthetic.cases).map(([name, id]) => `${name}=${id}`).join(', ')}`);
const figureCount = (set) => Object.values(set).reduce((n, st) => n + Object.keys(st).length, 0);
print(`figures: production ${figureCount(stays)}, synthetic ${figureCount(synthetic.stays)}, resource bookings ${figureCount(resourceBookings)} production + ${figureCount(synthetic.resourceBookings)} synthetic (stay figures are read at 4 instants)`);
print(`synthetic intakes: ${syntheticIntakes.expected.map((r) => `${r.intake}->${r.outcome}`).join(', ')}`);
print(`stays with an engine error: ${Object.entries(stays).filter(([, s]) => s['quote.error@capture']).map(([id]) => id).join(', ') || 'none'}`);
print(`intakes: ${Object.entries(intakesTables).map(([t, rows]) => `${t} ${rows.length}`).join(', ')}; replayed ${intakesExpected.length}: ${intakesExpected.map((r) => `${r.intake}->${r.outcome}`).join(', ') || 'none'}`);
print(`tables in inputs.json: ${Object.entries(inputsTables).map(([t, rows]) => `${t} ${rows.length}`).join(', ')}`);

if (!args.includes('--no-verify')) {
  const env = { ...process.env, PRICE_GATE_FIXTURE_DIR: path.resolve(outDir) };
  delete env.DB_PATH;
  const verify = spawnSync('node', ['--test', '--require', './src/tests/setup/isolateDefaultDb.js', 'src/tests/price-gate.unit.test.js', 'src/tests/price-gate-synthetic.unit.test.js', 'src/tests/platform-intake-replay.unit.test.js'], {
    cwd: path.join(root, 'server'), encoding: 'utf8', env,
  });
  const summary = `${verify.stdout}\n${verify.stderr}`.split('\n').filter((l) => /^# (pass|fail|skipped)/.test(l)).join(' | ');
  print(`self-check (the gate on a fresh database loaded from the fixture): ${verify.status === 0 ? 'GREEN' : 'RED'} ${summary}`);
  process.exit(verify.status === 0 ? 0 : 1);
}
